const lessons=[{"sentences":[{"speaker":"A","text":"Good morning because I left my backpack on the city bus this morning.","pauseAfterSeconds":0.2,"position":1,"audioStartSeconds":0,"audioEndSeconds":3.68},{"speaker":"B","text":"Good morning and do you remember the route number of that bus?","pauseAfterSeconds":0.2,"position":2,"audioStartSeconds":3.88,"audioEndSeconds":7.16},{"speaker":"A","text":"It was route forty two and I got off near the central station around eight.","pauseAfterSeconds":0.2,"position":3,"audioStartSeconds":7.36,"audioEndSeconds":11.6},{"speaker":"B","text":"That vehicle should arrive at the main depot in about twenty minutes.","pauseAfterSeconds":0.2,"position":4,"audioStartSeconds":11.8,"audioEndSeconds":15.4},{"speaker":"A","text":"Can I wait there to collect it because my passport is inside?","pauseAfterSeconds":0.2,"position":5,"audioStartSeconds":15.6,"audioEndSeconds":18.96},{"speaker":"B","text":"Yes although you must bring some official photo identification with you.","pauseAfterSeconds":0.2,"position":6,"audioStartSeconds":19.16,"audioEndSeconds":23},{"speaker":"A","text":"I always carry my driver license so that will work perfectly.","pauseAfterSeconds":0.2,"position":7,"audioStartSeconds":23.2,"audioEndSeconds":26.8},{"speaker":"B","text":"Please go to the customer service desk when you reach the office.","pauseAfterSeconds":0.2,"position":8,"audioStartSeconds":27,"audioEndSeconds":30.12},{"speaker":"A","text":"Should I speak with the manager or another staff member there?","pauseAfterSeconds":0.2,"position":9,"audioStartSeconds":30.32,"audioEndSeconds":33.44},{"speaker":"B","text":"Any colleague at the front desk can check the secure storage room.","pauseAfterSeconds":0.2,"position":10,"audioStartSeconds":33.64,"audioEndSeconds":37.08},{"speaker":"A","text":"What happens if nobody has handed the bag in yet?","pauseAfterSeconds":0.2,"position":11,"audioStartSeconds":37.28,"audioEndSeconds":40.24},{"speaker":"B","text":"We will contact the driver directly through our radio system immediately.","pauseAfterSeconds":0.2,"position":12,"audioStartSeconds":40.44,"audioEndSeconds":44.28},{"speaker":"A","text":"That is wonderful news because I was really worried about losing everything.","pauseAfterSeconds":0.2,"position":13,"audioStartSeconds":44.48,"audioEndSeconds":48.64},{"speaker":"B","text":"Lost property items are usually returned safely if passengers act quickly.","pauseAfterSeconds":0.2,"position":14,"audioStartSeconds":48.84,"audioEndSeconds":53.16},{"speaker":"A","text":"I will drive there right now so I arrive before ten o clock.","pauseAfterSeconds":0.2,"position":15,"audioStartSeconds":53.36,"audioEndSeconds":56.88},{"speaker":"B","text":"Drive carefully and we will see you at the depot soon.","pauseAfterSeconds":0.2,"position":16,"audioStartSeconds":57.08,"audioEndSeconds":60.2}],"questions":[{"prompt":"What is the main purpose of the traveller's call?","options":["To report a missing backpack.","To complain about a bus driver.","To book a ticket for tomorrow."],"answer":"A","evidenceSentence":1,"evidence":"Good morning because I left my backpack on the city bus this morning.","explanation":"Người nói A gọi điện để thông báo về chiếc ba lô bị bỏ quên trên xe buýt."},{"prompt":"Which bus route did the traveller take?","options":["Route twenty four.","Route forty two.","Route twelve."],"answer":"B","evidenceSentence":3,"evidence":"It was route forty two and I got off near the central station around eight.","explanation":"Hành khách xác nhận đã đi tuyến xe buýt số bốn mươi hai."},{"prompt":"What important item is inside the lost backpack?","options":["A laptop computer.","A wallet with cash.","A passport."],"answer":"C","evidenceSentence":5,"evidence":"Can I wait there to collect it because my passport is inside?","explanation":"Hành khách lo lắng vì có hộ chiếu ở bên trong chiếc ba lô."},{"prompt":"What must the traveller bring to claim the bag?","options":["Official photo identification.","A bus ticket from today.","A letter from the police."],"answer":"A","evidenceSentence":6,"evidence":"Yes although you must bring some official photo identification with you.","explanation":"Nhân viên yêu cầu phải mang theo giấy tờ tùy thân chính thức có ảnh."},{"prompt":"What will the staff do if the bag has not reached the depot yet?","options":["Call the police department.","Contact the driver via radio.","Search the central station."],"answer":"B","evidenceSentence":12,"evidence":"We will contact the driver directly through our radio system immediately.","explanation":"Nhân viên cho biết họ sẽ liên lạc trực tiếp với tài xế qua hệ thống bộ đàm."},{"prompt":"What will the traveller do next?","options":["Wait at home for a phone call.","Drive to the depot immediately.","Take another bus to the station."],"answer":"B","evidenceSentence":15,"evidence":"I will drive there right now so I arrive before ten o clock.","explanation":"Hành khách sẽ lái xe đến kho chứa đồ ngay lập tức."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
